type Fixture=Awaited<ReturnType<typeof fixture>>;
function check(name:string,run:(f:Fixture)=>Promise<void>){test(name,async()=>{const f=await fixture();try{await run(f);}finally{await f.pg.close();}});}
const incomeRange={from:'2026-01-01',through:'2026-12-31'};
const income=(f:Fixture,patch:Record<string,string>={},as='master')=>f.request('reports/finance/tuition-income?'+new URLSearchParams({...incomeRange,...patch}),undefined,as);
const release=(f:Fixture,id:string,patch:Record<string,unknown>={},as='master',key?:string)=>f.request('finance/invoices/'+id+'/recognitions',{amount:'40',deferredAccount:{id:f.deferred.id,version:1},revenueAccount:{id:f.income.id,version:1},earnedOn:'2026-11-06',postedOn:'2026-11-07',period:{id:f.period.id,version:1},reference:'SERVICE-1',earningReview:'PRIVATE explicit service earning review;not independently certified',reason:'PRIVATE reviewed release',...patch},as,{key});
const unrelease=(f:Fixture,id:string,patch:Record<string,unknown>={},as='master',key?:string)=>f.request('finance/tuition-recognitions/'+id+'/void',{period:{id:f.period.id,version:1},postedOn:'2026-11-09',reason:'PRIVATE reviewed correction',...patch},as,{key});
check('tuition earning attribution includes actual release and inverse dates without changing original billings tax or document counts',async f=>{
 const issued=await f.issue();assert.equal(issued.response.status,201);await earned(f);const rid=await release(f,issued.body.data.id);assert.equal(rid.response.status,201);const before=await income(f,{through:'2026-11-06'});assert.equal(before.body.data.currencies[0].recognizedRevenue.minor,'10000');assert.equal(before.body.data.currencies[0].earningEvents,0);const report=await income(f),d=report.body.data,c=d.currencies[0];assert.equal(report.response.status,200,JSON.stringify(report.body));assert.equal(c.netBillings.minor,'20000');assert.equal(c.chargedTax.minor,'2600');assert.equal(c.earnedInvoiceRevenue.minor,'10000');assert.equal(c.subsequentlyEarnedRevenue.minor,'4000');assert.equal(c.recognizedRevenue.minor,'14000');assert.equal(c.netDeferredChange.minor,'6000');assert.equal(c.documentEvents,2);assert.equal(c.earningEvents,1);assert.equal(c.sourceEvents,3);for(const rows of Object.values(d.charts) as any[][]){assert.equal(rows.reduce((n:bigint,r:any)=>n+BigInt(r.recognizedRevenue.minor),0n),14000n);assert.equal(rows.reduce((n:number,r:any)=>n+r.sourceEvents,0),3);}assert.equal(d.accountBasis,'original_invoice_consideration_account');assert.equal(d.deferredBalanceDetermined,false);assert.equal(d.subsequentRecognitionJournalsIncluded,true);assert.equal(d.manualJournalsIncluded,false);assert.doesNotMatch(JSON.stringify(d),/PRIVATE|earningReview|approvalId|source_snapshot/);assert.equal((await f.request('reports/finance/profit-loss?'+new URLSearchParams(incomeRange))).body.data.currencies[0].income.minor,c.recognizedRevenue.minor);
 const only=await income(f,{from:'2026-11-07',through:'2026-11-07'}),o=only.body.data.currencies[0];assert.equal(o.documentEvents,0);assert.equal(o.earningEvents,1);assert.equal(o.sourceEvents,1);assert.equal(o.netBillings.minor,'0');assert.equal(o.chargedTax.minor,'0');assert.equal(o.recognizedRevenue.minor,'4000');assert.equal(o.netDeferredChange.minor,'-4000');assert.equal(only.body.data.charts.account[0].key,f.deferred.id);assert.equal((await unrelease(f,rid.body.data.id)).response.status,201);const inverse=await income(f,{from:'2026-11-09',through:'2026-11-09'});assert.equal(inverse.body.data.currencies[0].recognizedRevenue.minor,'-4000');assert.equal(inverse.body.data.currencies[0].netDeferredChange.minor,'4000');assert.equal(inverse.body.data.charts.event[0].key,'recognition_reversal');const after=await income(f);assert.equal(after.body.data.currencies[0].recognizedRevenue.minor,'10000');assert.equal(after.body.data.currencies[0].earningEvents,2);assert.equal(after.body.data.currencies[0].documentEvents,2);assert.equal((await income(f,{through:'2026-11-08'})).body.data.currencies[0].recognizedRevenue.minor,'14000');assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,4);
});
