test('tuition recognition native commit rechecks late source changes and rolls back before identical retry',{skip:!process.env.TEST_DATABASE_URL},async()=>{
 const f=await fixture(),runtime=f.pg.runtime!,connect=runtime.connect.bind(runtime),failures:string[]=[];try{const issued=await f.issue();assert.equal(issued.response.status,201);runtime.connect=async()=>{const c=await connect();return {async query<Row>(sql:string,params?:unknown[]){try{return await c.query<Row>(sql,params);}catch(error){if(sql==='COMMIT'&&error&&typeof error==='object'&&'message'in error)failures.push(String(error.message));throw error;}},release:c.release.bind(c)};};
 await f.pg.exec("CREATE FUNCTION public.recognition_late_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF NEW.line_number=2 AND EXISTS(SELECT 1 FROM public.tuition_recognitions WHERE academy_id=NEW.academy_id AND id=NEW.journal_id) THEN UPDATE public.finance_account_revisions SET active=false WHERE academy_id=NEW.academy_id AND account_id=NEW.account_id AND version=NEW.account_version;END IF;RETURN NULL;END$$;CREATE TRIGGER recognition_late_source AFTER INSERT ON public.finance_journal_lines FOR EACH ROW EXECUTE FUNCTION public.recognition_late_source()");const key=randomUUID(),r=await release(f,issued.body.data.id,{},'master',key);assert.equal(r.response.status,400,JSON.stringify(r.body));assert.ok(failures.includes('TUITION_RECOGNITION_SOURCE_CHANGED'),JSON.stringify(failures));assert.equal((await f.pg.query('SELECT * FROM public.tuition_recognitions')).rows.length,0);assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,1);assert.equal((await f.pg.query('SELECT active FROM public.finance_account_revisions WHERE account_id=$1',[f.income.id])).rows[0].active,true);await f.pg.exec('DROP TRIGGER recognition_late_source ON public.finance_journal_lines');assert.equal((await release(f,issued.body.data.id,{},'master',key)).response.status,201);
 }finally{runtime.connect=connect;await f.pg.close();}
});
